#pragma once
// Bitmap fonts (Spleen, BSD-2-Clause) and text rendering.
#include <stdint.h>
#include "gfx.h"

struct font {
    uint8_t w, h;          // cell size in pixels
    uint8_t first, last;   // covered character range
    const uint16_t *rows;  // h rows per glyph, bit 15 = leftmost pixel
};

extern const struct font font_8x16;
extern const struct font font_12x24;
extern const struct font font_16x32;

// Extra glyph slots generated by tools/bdf2c.py
#define CH_MIDDOT "\x7f"
#define CH_DEGREE "\x80"
#define CH_BULLET "\x81"

// ---- anti-aliased proportional fonts (Inter, SIL OFL 1.1) ----
struct aglyph {
    uint32_t off;          // into data[]
    uint8_t w, h;          // bitmap size
    int8_t bx, by;         // offset of the bitmap from (pen x, line top)
    uint8_t adv;           // advance in pixels
};
struct afont {
    uint8_t height, ascent;   // line height, baseline offset from line top
    uint8_t first, last;
    const struct aglyph *g;
    const uint8_t *data;      // 8-bit coverage
};
extern const struct afont afont_ui;       // Inter Regular 13
extern const struct afont afont_ui_med;   // Inter Medium 13
extern const struct afont afont_ui_bold;  // Inter SemiBold 13
extern const struct afont afont_small;    // Inter Regular 11
extern const struct afont afont_title;    // Inter Display SemiBold 24
#define CH_EMDASH "\x82"

int text_width(const struct afont *f, const char *s);
// Draws with the line box top at y. Returns the pen x after the text.
int text_draw(struct surface *s, const struct afont *f, int x, int y, const char *str, color_t c);
void text_center(struct surface *s, const struct afont *f, int x, int w, int y, const char *str, color_t c);

// ---- monospace bitmap fonts (Spleen) ----
int font_width(const struct font *f, const char *s);              // pixels
// Draw text with its cell top-left at (x,y). Returns the x after the text.
// If the color has alpha < 255 the glyph pixels are blended.
int gfx_text(struct surface *s, const struct font *f, int x, int y, const char *str, color_t c);
int gfx_text_n(struct surface *s, const struct font *f, int x, int y, const char *str, int n, color_t c);
int gfx_text_bold(struct surface *s, const struct font *f, int x, int y, const char *str, color_t c);
void gfx_glyph(struct surface *s, const struct font *f, int x, int y, unsigned char ch, color_t c);
// Horizontally centered in [x, x+w)
void gfx_text_center(struct surface *s, const struct font *f, int x, int w, int y, const char *str, color_t c);
